import type { Vars, VarValue } from "./types";

/**
 * Tiny safe expression evaluator for choice conditions.
 * Recursive-descent parser over a whitelist of operators; never touches eval(),
 * the Function constructor, or property access on arbitrary objects.
 */

type Token =
  | { kind: "num"; value: number }
  | { kind: "str"; value: string }
  | { kind: "ident"; value: string }
  | { kind: "op"; value: string };

const TWO_CHAR_OPS = ["==", "!=", ">=", "<=", "&&", "||"] as const;
const ONE_CHAR_OPS = new Set(["!", "(", ")", ">", "<"]);

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i]!;
    if (/\s/.test(ch)) {
      i++;
      continue;
    }
    if (/[0-9]/.test(ch)) {
      let j = i;
      while (j < src.length && /[0-9.]/.test(src[j]!)) j++;
      const num = Number(src.slice(i, j));
      if (!Number.isFinite(num)) throw new Error(`Bad number at ${i}: "${src.slice(i, j)}"`);
      tokens.push({ kind: "num", value: num });
      i = j;
      continue;
    }
    if (ch === '"' || ch === "'") {
      const end = src.indexOf(ch, i + 1);
      if (end === -1) throw new Error(`Unterminated string starting at ${i}`);
      tokens.push({ kind: "str", value: src.slice(i + 1, end) });
      i = end + 1;
      continue;
    }
    if (/[A-Za-z_]/.test(ch)) {
      let j = i;
      while (j < src.length && /[A-Za-z0-9_]/.test(src[j]!)) j++;
      tokens.push({ kind: "ident", value: src.slice(i, j) });
      i = j;
      continue;
    }
    const two = src.slice(i, i + 2);
    if ((TWO_CHAR_OPS as readonly string[]).includes(two)) {
      tokens.push({ kind: "op", value: two });
      i += 2;
      continue;
    }
    if (ONE_CHAR_OPS.has(ch)) {
      tokens.push({ kind: "op", value: ch });
      i += 1;
      continue;
    }
    throw new Error(`Unexpected character "${ch}" at position ${i}`);
  }
  return tokens;
}

function truthy(v: VarValue | boolean): boolean {
  return Boolean(v);
}

class Parser {
  private pos = 0;
  constructor(
    private readonly tokens: Token[],
    private readonly vars: Vars,
  ) {}

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private expectOp(value: string): void {
    const tok = this.peek();
    if (!tok || tok.kind !== "op" || tok.value !== value) {
      throw new Error(`Expected "${value}", got ${tok ? JSON.stringify(tok) : "end of input"}`);
    }
    this.pos++;
  }

  private matchOp(...values: string[]): string | undefined {
    const tok = this.peek();
    if (tok && tok.kind === "op" && values.includes(tok.value)) {
      this.pos++;
      return tok.value;
    }
    return undefined;
  }

  parse(): boolean {
    const v = this.parseOr();
    if (this.pos !== this.tokens.length) {
      throw new Error(`Trailing input at token ${this.pos}`);
    }
    return truthy(v);
  }

  private parseOr(): VarValue | boolean {
    let left = this.parseAnd();
    while (this.matchOp("||")) {
      const right = this.parseAnd();
      left = truthy(left) || truthy(right);
    }
    return left;
  }

  private parseAnd(): VarValue | boolean {
    let left = this.parseCmp();
    while (this.matchOp("&&")) {
      const right = this.parseCmp();
      left = truthy(left) && truthy(right);
    }
    return left;
  }

  private parseCmp(): VarValue | boolean {
    const left = this.parseUnary();
    const op = this.matchOp("==", "!=", ">=", "<=", ">", "<");
    if (!op) return left;
    const right = this.parseUnary();
    return compare(op, left, right);
  }

  private parseUnary(): VarValue | boolean {
    if (this.matchOp("!")) return !truthy(this.parseUnary());
    if (this.matchOp("(")) {
      const v = this.parseOr();
      this.expectOp(")");
      return v;
    }
    const tok = this.peek();
    if (!tok) throw new Error("Unexpected end of expression");
    this.pos++;
    if (tok.kind === "num") return tok.value;
    if (tok.kind === "str") return tok.value;
    // Identifier: known variable value, or false if unset (safe default for gating).
    if (tok.value === "true") return true;
    if (tok.value === "false") return false;
    const value = this.vars[tok.value];
    return value === undefined ? false : value;
  }
}

function compare(op: string, a: VarValue | boolean, b: VarValue | boolean): boolean {
  switch (op) {
    case "==":
      return a === b;
    case "!=":
      return a !== b;
  }
  const numA = typeof a === "number" ? a : undefined;
  const numB = typeof b === "number" ? b : undefined;
  if (numA !== undefined && numB !== undefined) {
    if (op === ">") return numA > numB;
    if (op === "<") return numA < numB;
    if (op === ">=") return numA >= numB;
    return numA <= numB;
  }
  if (typeof a === "string" && typeof b === "string") {
    if (op === ">") return a > b;
    if (op === "<") return a < b;
    if (op === ">=") return a >= b;
    return a <= b;
  }
  throw new Error(`Cannot order ${JSON.stringify(a)} ${op} ${JSON.stringify(b)}`);
}

/** Evaluate a condition expression against the variable store. */
export function evaluateCondition(expr: string, vars: Vars): boolean {
  return new Parser(tokenize(expr), vars).parse();
}

