/** Variable values supported by the engine. */
export type VarValue = string | number | boolean;

/** The variable store for a playthrough. */
export type Vars = Record<string, VarValue>;

/**
 * Effects a choice applies when taken.
 * - number: additive delta applied to the variable (missing vars start at 0)
 * - string | boolean: absolute assignment
 */
export type Effects = Record<string, number | string | boolean>;

export interface Choice {
  /** Label shown to the player. */
  text: string;
  /** Target passage id. */
  to: string;
  /** Optional condition expression, e.g. "gold >= 10 && met_king". */
  if?: string;
  /** Optional variable effects, e.g. { gold: +5 }. */
  effects?: Effects;
}

export interface Passage {
  id: string;
  text: string;
  choices?: Choice[];
}

export interface Story {
  start: string;
  passages: Record<string, Passage>;
}

