import { evaluateCondition } from "./evaluator";
import type { Choice, Effects, Passage, Story, Vars } from "./types";

export * from "./types";
export { evaluateCondition } from "./evaluator";

/**
 * Apply choice effects to a variable store.
 * Pure: returns a new store; numbers are deltas, everything else is assigned.
 */
export function applyEffects(vars: Vars, effects?: Effects): Vars {
  if (!effects) return { ...vars };
  const out: Vars = { ...vars };
  for (const [key, value] of Object.entries(effects)) {
    if (typeof value === "number") {
      const current = typeof out[key] === "number" ? (out[key] as number) : 0;
      out[key] = current + value;
    } else {
      out[key] = value;
    }
  }
  return out;
}

/** Choices currently offered in a passage, filtered by their conditions. Deterministic: input order is preserved. */
export function offeredChoices(story: Story, passageId: string, vars: Vars): Choice[] {
  const passage = requirePassage(story, passageId);
  return (passage.choices ?? []).filter((c) => !c.if || evaluateCondition(c.if, vars));
}

function requirePassage(story: Story, id: string): Passage {
  const p = story.passages[id];
  if (!p) throw new Error(`Unknown passage: "${id}"`);
  return p;
}

export interface StepResult {
  passageId: string;
  vars: Vars;
}

/**
 * Take the choice at `choiceIndex` among the *offered* choices of the current
 * passage. Applies its effects and moves to the target. Pure.
 */
export function step(story: Story, passageId: string, choiceIndex: number, vars: Vars): StepResult {
  const offered = offeredChoices(story, passageId, vars);
  const choice = offered[choiceIndex];
  if (!choice) throw new Error(`No offered choice at index ${choiceIndex} in "${passageId}"`);
  return { passageId: choice.to, vars: applyEffects(vars, choice.effects) };
}

/** A complete deterministic playthrough: sequence of offered-choice indices from the start passage. */
export type Path = number[];

export interface WalkResult {
  finalPassageId: string;
  finalVars: Vars;
  trail: { passageId: string; text: string; chosenText: string | null }[];
}

/** Walk a scripted path from the story's start. Same inputs always produce identical outputs. */
export function walk(story: Story, path: Path, initialVars: Vars = {}): WalkResult {
  let passageId = story.start;
  let vars: Vars = { ...initialVars };
  const trail: WalkResult["trail"] = [];

  for (const choiceIndex of path) {
    const passage = requirePassage(story, passageId);
    const offered = offeredChoices(story, passageId, vars);
    const choice = offered[choiceIndex];
    if (!choice) {
      throw new Error(`Dead end: no offered choice at index ${choiceIndex} in "${passageId}"`);
    }
    trail.push({ passageId, text: passage.text, chosenText: choice.text });
    const next = step(story, passageId, choiceIndex, vars);
    passageId = next.passageId;
    vars = next.vars;
  }

  trail.push({ passageId, text: requirePassage(story, passageId).text, chosenText: null });
  return { finalPassageId: passageId, finalVars: vars, trail };
}

/** Static validation: returns a list of problems (empty means the story graph is well-formed). */
export function validateStory(story: Story): string[] {
  const errors: string[] = [];
  if (!story.passages[story.start]) {
    errors.push(`Start passage "${story.start}" does not exist`);
  }
  for (const [id, passage] of Object.entries(story.passages)) {
    if (!passage.text || passage.text.trim() === "") errors.push(`Passage "${id}" has empty text`);
    for (const [i, choice] of (passage.choices ?? []).entries()) {
      if (!story.passages[choice.to]) {
        errors.push(`Choice ${i} ("${choice.text}") in passage "${id}" targets missing passage "${choice.to}"`);
      }
      if (choice.if) {
        try {
          evaluateCondition(choice.if, {});
        } catch (e) {
          errors.push(`Condition "${choice.if}" on choice ${i} of "${id}" failed to parse: ${(e as Error).message}`);
        }
      }
    }
  }
  return errors;
}

