import type { Story } from "./engine";

/**
 * "The Sunken Crown" — a 10-passage story.
 * The good ending ("Claim the Sunken Crown") is gated on gold >= 10 && met_king.
 */
const story: Story = {
  start: "start",
  passages: {
    start: {
      id: "start",
      text:
        "Dawn finds you on the dock of Brinemouth, a basket of silverfish at your feet. " +
        "The tide smells of iron, and somewhere beyond the rooftops, bells are ringing for the old king's funeral.",
      choices: [{ text: "Step up into the town square.", to: "square" }],
    },

    square: {
      id: "square",
      text:
        "The square hums under grey light. Stalls to the east, the forest road west, " +
        "a tavern's warm windows north, and the castle's black gates rising south.",
      choices: [
        { text: "Visit the market stalls.", to: "market" },
        { text: "Take the forest road.", to: "forest" },
        { text: "Warm yourself in the tavern.", to: "tavern" },
        { text: "Approach the castle gate.", to: "castle_gate" },
        {
          text: "Claim the Sunken Crown from the royal vault.",
          to: "coronation",
          if: "gold >= 10 && met_king",
        },
      ],
    },

    market: {
      id: "market",
      text:
        "Fishmongers shout over one another. A cook with flour on her sleeves eyes your silverfish " +
        "and names a price that would make her mother weep.",
      choices: [
        { text: "Sell the silverfish.", to: "square", effects: { gold: 6 } },
        { text: "Keep walking.", to: "square" },
      ],
    },

    forest: {
      id: "forest",
      text:
        "Pine shadows swallow the road. Beneath a mossy hollow you glimpse the glint of an old coin purse — " +
        "dropped, by the look of it, by some fleeing noble years ago.",
      choices: [
        { text: "Search the mossy hollow.", to: "square", effects: { gold: 5 } },
        { text: "Leave it for the crows.", to: "square" },
      ],
    },

    tavern: {
      id: "tavern",
      text:
        "Inside the Salt-Stained Bell, an old boatman nurses something strong and offers you a berth " +
        "on the morning tide. \"Kings come and go,\" he says. \"The river doesn't.\"",
      choices: [
        { text: "Sail away with the boatman.", to: "river_end" },
        { text: "Finish your drink and return to the square.", to: "square", effects: { heard_rumor: true } },
      ],
    },

    castle_gate: {
      id: "castle_gate",
      text:
        "Guards in mourning black flank the gate. One squints at you. \"State your business with his majesty's household, or move along.\"",
      choices: [
        { text: "Present yourself to the royal guard.", to: "throne_room" },
        { text: "Turn away.", to: "wanderer_end" },
      ],
