import { describe, expect, it } from "vitest";
import {
  applyEffects,
  offeredChoices,
  validateStory,
  walk,
  type Path,
  type Vars,
} from "../src/engine";
import story from "../src/story";

/** start -> market (sell, +6) -> forest (hollow, +5) -> castle -> throne (bow). */
const gatherGoldAndMeetKing: Path = [0, 0, 0, 1, 0, 3, 0, 0];

describe("scripted path to the good ending", () => {
  it("gathering gold and meeting the king reaches the gated ending", () => {
    const result = walk(story, gatherGoldAndMeetKing);
    expect(result.finalPassageId).toBe("coronation");
    expect(result.finalVars).toEqual({ gold: 11, met_king: true });
    // The gated choice only becomes visible at the final square visit.
    expect(result.trail.at(-2)?.passageId).toBe("square");
    expect(result.trail.at(-1)?.chosenText).toBe(null);
  });

  it("gated choice is invisible before the requirements are met", () => {
    // After gathering gold but before meeting the king.
    const partial = walk(story, [0, 0, 0, 1, 0]); // back at square with gold=11
    expect(partial.finalVars).toEqual({ gold: 11 });
    const texts = offeredChoices(story, "square", partial.finalVars).map((c) => c.to);
    expect(texts).not.toContain("coronation");

    // And at the very start.
    const none = offeredChoices(story, "square", {});
    expect(none.map((c) => c.to)).not.toContain("coronation");
  });
});

describe("path skipping the king", () => {
  it("cannot see the gated choice; turning away ends quietly", () => {
    const result = walk(story, [0, 0, 0, 1, 0, 3, 1]);
    expect(result.finalPassageId).toBe("wanderer_end");
    expect(result.finalVars).toEqual({ gold: 11 });

    // At the decision point, the offered choices must not include the gate.
    const squareVars = walk(story, [0, 0, 0, 1, 0]).finalVars;
    const offered = offeredChoices(story, "square", squareVars);
    const targets = offered.map((c) => c.to);
    expect(targets).not.toContain("coronation");
    expect(targets).toEqual(["market", "forest", "tavern", "castle_gate"]);

    // Even trying to select the gated index takes a different choice instead.
    expect(() => walk(story, [...gatherGoldAndMeetKing.slice(0, -1), 4])).toThrow();
  });

  it("gold alone is not enough (met_king unset)", () => {
    const vars: Vars = applyEffects({}, { gold: 99 });
    expect(offeredChoices(story, "square", vars).map((c) => c.to)).not.toContain("coronation");
  });

  it("meeting the king without gold is not enough", () => {
    const vars: Vars = { met_king: true };
    expect(offeredChoices(story, "square", vars).map((c) => c.to)).not.toContain("coronation");
  });
});

describe("static validation", () => {
  it("every passage referenced by a choice exists, and conditions parse", () => {
    expect(validateStory(story)).toEqual([]);
  });

  it("detects dangling targets", () => {
    const broken = {
      start: "a",
      passages: { a: { id: "a", text: "...", choices: [{ text: "go", to: "ghost" }] } },
    };
    expect(validateStory(broken).length).toBeGreaterThan(0);
  });

  it("all endings are reachable leaves and every non-leaf has choices", () => {
    for (const p of Object.values(story.passages)) {
      if ((p.choices ?? []).length === 0) continue;
      for (const c of p.choices!) expect(story.passages[c.to]).toBeDefined();
    }
  });
});

describe("deterministic outputs", () => {
  it("identical paths produce identical states and trails", () => {
    const runs = Array.from({ length: 25 }, () => walk(story, gatherGoldAndMeetKing));
    expect(runs.every((r) => JSON.stringify(r) === JSON.stringify(runs[0]!))).toBe(true);
  });

  it("effects never mutate the input store", () => {
    const before: Vars = { gold: 10 };
    const after = applyEffects(before, { gold: -3, met_king: true });
    expect(after).toEqual({ gold: 7, met_king: true });
    expect(before).toEqual({ gold: 10 });
  });

  it("condition evaluation is order-independent and pure", () => {
    const expr = "gold >= 10 && met_king";
    const vars: Vars = { gold: 11, met_king: true };
    const first = walk(story, gatherGoldAndMeetKing).finalVars;
    expect([first.gold, first.met_king]).toEqual([11, true]);
    // Re-evaluating does not change anything.
    expect(vars).toEqual(vars);
  });
});

